import warnings
from sympy.utilities.decorator import deprecated
from sympy.utilities.exceptions import SymPyDeprecationWarning

kw = dict(deprecated_since_version='1.10', active_deprecations_target='active-deprecations')

def check_warns(f):
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        r = f()
        assert any(issubclass(x.category, SymPyDeprecationWarning) for x in w), "no warning"
        return r

@deprecated('dep', **kw)
class Both:
    def __new__(cls, arg):
        if arg == 0:
            return arg
        return object.__new__(cls)
    def __init__(self, arg):
        self.arg = arg + 100

i = check_warns(lambda: Both(1))
assert i.arg == 101
assert check_warns(lambda: Both(0)) == 0

@deprecated('dep', **kw)
class KwOnly:
    def __init__(self, x=5):
        self.x = x

assert check_warns(lambda: KwOnly(x=7)).x == 7

